{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "The close mGluR5 PET analogue [11C]MPEPy easily crosses the BBB in PET studies, even though it is a P-gp efflux substrate; this directly supports meaningful CNS access for the query's ethynylpyridine/methoxyaryl scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "PET studies in rhesus monkeys show that related alkyne-containing mGluR5 tracers readily enter the brain and provide large, long-lasting specific signals, supporting brain penetration of the query's alkyne-linked aromatic PET tracer.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A close mGluR5 PET tracer with an ethynyl heteroaryl core shows rapid brain uptake in rhesus monkeys with a peak striatal uptake of about 3.1 SUV, demonstrating robust CNS entry for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Methoxamine, a methoxy-substituted aromatic small molecule, reaches a 1:1 plasma-brain equilibrium within 15 minutes after intravenous administration, showing that such compounds can achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Pterostilbene, a lipophilic methoxy-substituted aromatic compound, reaches 10.3 µg/g in mouse brain after oral administration, confirming that this type of structure readily crosses the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A related methoxy-substituted aromatic compound shows moderate initial brain uptake of about 1% ID/g in mice after intravenous injection and was described as readily crossing the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a carbon-11-labeled methoxyaryl-ethynylpyridine PET tracer closely related to mGluR5 tracers that readily enter the brain in rodents and monkeys. Multiple high-transfer direct BBB measurements support meaningful CNS access; P-gp efflux in one close analogue reduces free fraction but does not prevent brain entry. Therefore the prediction is pass.",
  "evidence_gaps": [
    "No direct in vivo brain uptake measurement for the exact query molecule; prediction relies on close structural analogues.",
    "Efflux transporter status of the query is not directly measured; if it is a P-gp substrate, unbound brain concentration may be lower but overall access remains meaningful."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

